"""Incremental snapshots of consumed inputs without retaining every full prefix.

Each delta is against the preceding input snapshot. Values and instrument orders
are still exactly replayable; data-source approval is not inferred from a hash.
"""
from copy import deepcopy
from collections.abc import Iterator
import json


MAX_JOURNAL_BYTES = 256 * 1024 * 1024


def _changes(old, new, path=()):
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(old.keys() - new.keys()):
            yield ["remove", [*path, key]]
        for key in sorted(new):
            if key not in old:
                yield ["set", [*path, key], deepcopy(new[key])]
            else:
                yield from _changes(old[key], new[key], (*path, key))
    elif isinstance(old, list) and isinstance(new, list):
        for index in range(min(len(old), len(new))):
            yield from _changes(old[index], new[index], (*path, index))
        if len(new) > len(old):
            yield ["append", list(path), deepcopy(new[len(old):])]
        elif len(new) < len(old):
            yield ["truncate", list(path), len(new)]
    elif type(old) is not type(new) or old != new:
        yield ["set", list(path), deepcopy(new)]


class InputJournal:
    """One current panel plus sparse changes, not a list of expanding panels."""
    def __init__(self):
        self.previous = {}
        self.deltas = []
        self.encoded_bytes = 0

    def append(self, snapshot):
        delta = list(_changes(self.previous, snapshot))
        self.encoded_bytes += len(json.dumps(delta, allow_nan=False, separators=(",", ":")).encode())
        if self.encoded_bytes > MAX_JOURNAL_BYTES:
            raise ValueError("research input journal exceeds bounded evidence budget")
        self.deltas.append(delta)
        self.previous = snapshot

    def finish(self):
        self.previous = {}
        return self.deltas


def iter_snapshots(deltas) -> Iterator[dict]:
    """Replay one independent snapshot at a time; callers need not retain them."""
    current = {}
    for delta in deltas:
        if not isinstance(delta, list):
            raise ValueError("invalid input delta")
        for change in delta:
            if not isinstance(change, list) or len(change) not in (2, 3):
                raise ValueError("invalid input change")
            operation, path = change[:2]
            if not isinstance(path, list) or any(type(key) not in (str, int) for key in path):
                raise ValueError("invalid input change path")
            if operation == "set" and not path:
                if len(change) != 3 or not isinstance(change[2], dict):
                    raise ValueError("invalid root snapshot")
                current = deepcopy(change[2])
                continue
            target = current
            for key in path[:-1]:
                target = target[key]
            if operation == "set" and len(change) == 3 and path:
                target[path[-1]] = deepcopy(change[2])
            elif operation == "remove" and len(change) == 2 and path:
                del target[path[-1]]
            elif operation in {"append", "truncate"} and len(change) == 3:
                target = target[path[-1]] if path else target
                if not isinstance(target, list):
                    raise ValueError("input change requires a list")
                if operation == "append" and isinstance(change[2], list):
                    target.extend(deepcopy(change[2]))
                elif operation == "truncate" and type(change[2]) is int and 0 <= change[2] <= len(target):
                    del target[change[2]:]
                else:
                    raise ValueError("invalid list change")
            else:
                raise ValueError("unknown input change")
        yield deepcopy(current)

"""Plan a narrowly scoped retirement; apply only a freshly revalidated plan hash.

No credentials, account data, IAM roles, buckets, or secrets are deleted. The
operator must review the exact host/project/instance plan before applying it.
Application deployment cannot implicitly invoke this maintenance command.
"""
from __future__ import annotations

import argparse
from hashlib import sha256
import json
from pathlib import Path
import re
import socket
import subprocess
from typing import Callable

UNITS = frozenset({
    "toss-foundation.service", "toss-foundation.timer", "toss-paper-operation.service",
    "toss-paper-operation.timer", "toss-research-automation@.service",
    "toss-research-automation@daily.service", "toss-research-automation@weekly.service",
    "toss-research-daily.timer", "toss-research-weekly.timer", "toss-research-prune.service",
    "toss-research-prune.timer", "toss-stock-recommendations.service", "toss-stock-recommendations.timer",
})
PREFIXES = ("toss-foundation", "toss-paper-operation", "toss-research-", "toss-stock-recommendations")
ALERTS = {
    "Toss Foundation audit failed": "foundation_audit_failed_count",
    "Toss Foundation runner heartbeat missing": "foundation_runner_ok_count",
    "Toss Foundation snapshot failed": "foundation_snapshot_failed_count",
    "Toss Foundation runner failed": "foundation_runner_failed_count",
    "Toss Foundation runner lock contention": "foundation_runner_lock_busy_count",
    "Toss Foundation backup upload heartbeat missing": "foundation_runner_backup_upload_ok_count",
}
METRICS = frozenset(ALERTS.values()) | {
    "foundation_snapshot_ok_count", "foundation_audit_ok_count", "foundation_runner_backup_ok_count",
}


def command(argv: list[str]) -> str:
    return subprocess.run(argv, check=True, capture_output=True, text=True, timeout=60).stdout


def identity(plan: dict) -> str:
    return sha256(json.dumps(plan, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def _file_identity(path: Path) -> dict:
    if path.is_symlink():
        return {"symlink": str(path.readlink())}
    if path.is_file():
        return {"sha256": sha256(path.read_bytes()).hexdigest()}
    raise ValueError("retired unit must be a file or symlink")


def systemd_plan(*, run: Callable = command, root: Path = Path("/etc/systemd/system"), host: str | None = None) -> dict:
    files = run(["systemctl", "list-unit-files", "--all", "--no-legend", "--no-pager"])
    loaded = run(["systemctl", "list-units", "--all", "--plain", "--no-legend", "--no-pager"])
    names = {line.split()[0] for text in (files, loaded) for line in text.splitlines() if line.split()}
    names |= {p.name for p in root.iterdir() if p.name.startswith(PREFIXES)}
    candidates = sorted(n for n in names if n.startswith(PREFIXES))
    unknown = sorted(set(candidates) - UNITS)
    if unknown:
        raise ValueError(f"unrecognized retired units require manual review: {unknown}")
    retained_files = {}
    for name in candidates:
        path = root/name
        if path.exists() or path.is_symlink():
            retained_files[name] = _file_identity(path)
        fragment = run(["systemctl", "show", name, "--property=FragmentPath", "--value"]).strip()
        if fragment and fragment != str(path):
            raise ValueError(f"unit outside reviewed systemd root: {name}")
    # Stop timers before services. Templates are unlinked after their known
    # instances are stopped; never ask systemctl to stop an abstract template.
    stop = sorted((n for n in candidates if "@.service" not in n), key=lambda n: (not n.endswith(".timer"), n))
    return {"schema": "legacy-retirement-plan-v1", "kind": "systemd", "host": host or socket.gethostname(),
            "root": str(root), "units": stop, "unit_files": retained_files,
            "commands": [["systemctl", "disable", "--now", n] for n in stop],
            "excluded": ["account databases", "artifacts", "environment files", "canonical units"]}


def _filters(policy: dict) -> list[str]:
    filters = []
    for condition in policy.get("conditions", []):
        body = condition.get("conditionThreshold") or condition.get("conditionAbsent")
        if not isinstance(body, dict) or not isinstance(body.get("filter"), str):
            raise ValueError("unrecognized alert condition requires manual review")
        filters.append(body["filter"])
    if not filters:
        raise ValueError("empty alert policy")
    return filters


def _exact_scope(filter_: str, instance: str, *, metric: str | None = None) -> bool:
    # Only accept conjunctions of simple equalities generated by the old
    # provisioner; an OR/subexpression must not escape the instance boundary.
    clauses = re.split(r"\s+AND\s+", filter_)
    pairs = {}
    for clause in clauses:
        match = re.fullmatch(r'\s*([A-Za-z_.]+)\s*=\s*"([^"\\]+)"\s*', clause)
        if not match or match[1] in pairs:
            return False
        pairs[match[1]] = match[2]
    if pairs.get("resource.type") != "gce_instance" or pairs.get("resource.labels.instance_id") != instance:
        return False
    if metric is not None:
        return pairs == {"resource.type": "gce_instance", "resource.labels.instance_id": instance,
                         "metric.type": "logging.googleapis.com/user/"+metric}
    return True


def gcp_plan(*, project: str, instance: str, policies: list, metrics: list) -> dict:
    if not re.fullmatch(r"[a-z][a-z0-9-]{4,61}[a-z0-9]", project) or not re.fullmatch(r"[0-9]+", instance):
        raise ValueError("explicit GCP project ID and numeric instance ID required")
    removed, retained = [], []
    all_names = [p.get("name") for p in policies]
    if len(all_names) != len(set(all_names)):
        raise ValueError("duplicate policy inventory")
    for policy in policies:
        title = policy.get("displayName")
        if title not in ALERTS:
            continue
        if not re.fullmatch(re.escape(f"projects/{project}/alertPolicies/")+r"[0-9]+", policy.get("name", "")):
            raise ValueError("policy is not in the explicitly selected project")
        filters = _filters(policy)
        if not all(_exact_scope(f, instance, metric=ALERTS[title]) for f in filters):
            retained.append({"name": policy["name"], "reason": "different-or-unverified-instance-scope"})
            continue
        removed.append(policy["name"])
    commands = [["gcloud", "monitoring", "policies", "delete", name, f"--project={project}", "--quiet"]
                for name in sorted(removed)]
    if len({m.get("name") for m in metrics}) != len(metrics):
        raise ValueError("duplicate metric inventory")
    # A dynamic/unsupported metric selector may refer to a shared metric even
    # without its literal name. Preserve all legacy metrics in that case.
    unknown_selectors = False
    for policy in policies:
        if policy.get("name") in removed:
            continue
        try:
            filters = _filters(policy)
            if any(not re.search(r'metric\.type\s*=\s*"[A-Za-z0-9_./-]+"', f) for f in filters):
                unknown_selectors = True
        except ValueError:
            unknown_selectors = True
    for metric in metrics:
        name = metric.get("name")
        if name not in METRICS:
            continue
        references = [p for p in policies if p.get("name") not in removed and
                      f"logging.googleapis.com/user/{name}" in json.dumps(p)]
        if unknown_selectors or references or not _exact_scope(metric.get("filter", ""), instance):
            retained.append({"name": name, "reason": "shared-or-unverified-metric"})
        else:
            commands.append(["gcloud", "logging", "metrics", "delete", name, f"--project={project}", "--quiet"])
    return {"schema": "legacy-retirement-plan-v1", "kind": "gcp", "project": project, "instance_id": instance,
            "inventory_hash": identity({"policies": sorted(policies, key=lambda p:p['name']),
                                        "metrics": sorted(metrics, key=lambda m:m['name'])}),
            "commands": commands, "retained_for_review": retained,
            "excluded": ["IAM", "secrets", "buckets", "datasets", "shared/canonical alerts", "Ops Agent config"]}


def apply_plan(plan: dict, expected_hash: str, *, run: Callable = command) -> None:
    if identity(plan) != expected_hash:
        raise ValueError("retirement plan changed; review the fresh plan")
    for argv in plan["commands"]:
        run(argv)
    if plan["kind"] == "systemd":
        root = Path(plan["root"])
        for name, recorded in plan["unit_files"].items():
            path = root/name
            # systemctl disable may already remove an alias symlink. No other
            # process may substitute a different file after the plan was read.
            if not path.exists() and not path.is_symlink():
                continue
            if _file_identity(path) != recorded:
                raise ValueError("unit changed during retirement")
            path.unlink()
        run(["systemctl", "daemon-reload"])
        for name in plan["units"]:
            state = run(["systemctl", "show", name, "--property=ActiveState", "--value"]).strip()
            if state not in {"inactive", "failed", ""}:
                raise ValueError("retired unit remains active")


def main(argv=None) -> int:
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("kind", choices=("systemd", "gcp"))
    parser.add_argument("--project")
    parser.add_argument("--instance-id")
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--expect-plan-sha256")
    args=parser.parse_args(argv)
    if args.apply and not args.expect_plan_sha256:
        parser.error("--apply requires a reviewed --expect-plan-sha256")
    if args.kind == "systemd":
        plan=systemd_plan()
    else:
        if not args.project or not args.instance_id:
            parser.error("gcp requires --project and --instance-id")
        # These reads do not fetch credentials or broker/account payloads.
        policies=json.loads(command(["gcloud", "monitoring", "policies", "list", f"--project={args.project}", "--format=json"]))
        metrics=json.loads(command(["gcloud", "logging", "metrics", "list", f"--project={args.project}", "--format=json"]))
        plan=gcp_plan(project=args.project, instance=args.instance_id, policies=policies, metrics=metrics)
    print(json.dumps({"plan_sha256": identity(plan), "plan": plan}, sort_keys=True, indent=2))
    if args.apply:
        apply_plan(plan, args.expect_plan_sha256)
        print("scoped_retirement_applied=true")
    # Even a successful scoped retirement is not complete GCP operational acceptance.
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Resolve shipped runtime contracts independently of the process directory."""
from pathlib import Path
import sys


def resource_root() -> Path:
    installed = Path(sys.prefix) / "share" / "toss-trading"
    checkout = Path(__file__).resolve().parents[3]
    for root in (checkout, installed):
        if (root / "config/application.yaml").is_file() and (root / "schemas/asset_management.sql").is_file():
            return root
    raise FileNotFoundError("canonical runtime resources are not installed")

"""ALFRED normalization through the existing raw-first immutable data boundary.

Date-only vintages are not invented intraday publication timestamps. Missing
values remain versioned tombstones. No network client or new data store lives
here; transport and credential/rights approval remain upstream responsibilities.
"""
from __future__ import annotations

from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
from typing import Mapping

from .immutable import ImmutableDatasetStore, IngestionResult, ProviderDatasetAdapter
from .phase9 import ProviderBatch
from ..domain.errors import DataQualityError

SOURCE = "fred-alfred"
DATASET = "series-observation-revisions"
SCHEMA_VERSION = "alfred-vintages-v1"
SERIES = frozenset({"DGS2", "DGS10", "CPIAUCSL", "UNRATE", "FEDFUNDS"})
ROW_SCHEMA = {
    "provider_entity_id": "string", "observation_date": "string", "value": "string",
    "realtime_start": "string", "realtime_end": "string", "value_status": "string",
    "output_type": "integer",
}


def _day(value: object) -> date:
    if not isinstance(value, str):
        raise DataQualityError("ALFRED_DATE_INVALID")
    try:
        result = date.fromisoformat(value)
    except ValueError as exc:
        raise DataQualityError("ALFRED_DATE_INVALID") from exc
    if result.isoformat() != value:
        raise DataQualityError("ALFRED_DATE_INVALID")
    return result


def normalize_vintages(body: object, *, series_id: str, output_type: int) -> list[dict]:
    if series_id not in SERIES or type(output_type) is not int or output_type not in (1, 3):
        raise DataQualityError("ALFRED_REQUEST_CONTRACT_INVALID")
    if not isinstance(body, dict) or not isinstance(body.get("observations"), list):
        raise DataQualityError("ALFRED_OBSERVATIONS_MISSING")
    observations = body["observations"]
    # Partial pages must be assembled by the acquisition owner before admission.
    if (type(body.get("count")) is not int or body["count"] != len(observations)
            or type(body.get("offset")) is not int or body["offset"] != 0):
        raise DataQualityError("ALFRED_INCOMPLETE_PAGE")
    unique: dict[tuple[str, str], dict] = {}
    for observation in observations:
        if not isinstance(observation, dict):
            raise DataQualityError("ALFRED_OBSERVATION_INVALID")
        period = _day(observation.get("date"))
        if output_type == 1:
            versions = [(observation.get("realtime_start"), observation.get("realtime_end"), observation.get("value"))]
        else:
            prefix = f"{series_id}_"
            columns = [key for key in observation if key != "date"]
            if not columns or any(not isinstance(key, str) or not key.startswith(prefix) for key in columns):
                raise DataQualityError("ALFRED_VINTAGE_COLUMN_INVALID")
            versions = []
            for column in columns:
                suffix = column[len(prefix):]
                if len(suffix) != 8 or not suffix.isascii() or not suffix.isdigit():
                    raise DataQualityError("ALFRED_VINTAGE_COLUMN_INVALID")
                versions.append((f"{suffix[:4]}-{suffix[4:6]}-{suffix[6:]}", "9999-12-31", observation[column]))
        for start_value, end_value, raw_value in versions:
            start, end = _day(start_value), _day(end_value)
            if start > end or start < period or not isinstance(raw_value, str):
                raise DataQualityError("ALFRED_VINTAGE_INVALID")
            text = raw_value.strip()
            if text != ".":
                try:
                    value = Decimal(text)
                except InvalidOperation as exc:
                    raise DataQualityError("ALFRED_VALUE_INVALID") from exc
                if not value.is_finite():
                    raise DataQualityError("ALFRED_VALUE_INVALID")
                text = str(value)
            row = dict(provider_entity_id=series_id, observation_date=period.isoformat(),
                       value=text, realtime_start=start.isoformat(), realtime_end=end.isoformat(),
                       value_status="MISSING" if text == "." else "OBSERVED", output_type=output_type)
            key = (row["observation_date"], row["realtime_start"])
            if key in unique and unique[key] != row:
                raise DataQualityError("ALFRED_CONFLICTING_VINTAGE")
            unique[key] = row
    rows = [unique[key] for key in sorted(unique)]
    for index, row in enumerate(rows[:-1]):
        following = rows[index + 1]
        if row["observation_date"] != following["observation_date"]:
            continue
        if output_type == 3:
            row["realtime_end"] = (_day(following["realtime_start"]) - timedelta(days=1)).isoformat()
        elif row["realtime_end"] >= following["realtime_start"]:
            raise DataQualityError("ALFRED_OVERLAPPING_VINTAGE")
    return rows


def ingest_alfred(batch: ProviderBatch, store: ImmutableDatasetStore) -> IngestionResult:
    """Admit a complete decoded response; never request credentials or fetch data."""
    if (batch.source, batch.dataset, batch.schema_version, batch.endpoint, batch.http_method) != (
            SOURCE, DATASET, SCHEMA_VERSION, "/fred/series/observations", "GET"):
        raise DataQualityError("ALFRED_BATCH_CONTRACT_INVALID")
    request = batch.request
    if not isinstance(request, Mapping) or request.get("units", "lin") != "lin":
        raise DataQualityError("ALFRED_REQUEST_CONTRACT_INVALID")
    series_id = request.get("series_id")
    output_type = request.get("output_type", 1)
    if series_id not in SERIES or type(output_type) is not int or output_type not in (1, 3):
        raise DataQualityError("ALFRED_REQUEST_CONTRACT_INVALID")

    def normalize(raw):
        return normalize_vintages(raw, series_id=series_id, output_type=output_type)

    return ProviderDatasetAdapter(store).ingest(
        body=batch.body, request=batch.request, source=batch.source, dataset=batch.dataset,
        endpoint=batch.endpoint, http_method=batch.http_method,
        retrieved_at=batch.received_at, available_at=batch.available_at,
        provider_timestamp=batch.provider_timestamp, license_tag=batch.license_tag,
        code_revision=batch.code_revision, schema_version=SCHEMA_VERSION,
        raw_schema={"observations": "array"}, schema=ROW_SCHEMA,
        instrument_mapping={series_id: series_id}, normalize=normalize,
        status_code=batch.status_code, provider_entity_field="provider_entity_id",
        canonical_entity_field="series_id",
    )
